<script>
 import {onMount} from 'svelte';import {goto} from '$app/navigation';import {listDevices,listSites} from '$lib/api.js';import {devices,notify,user} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';import Modal from '$lib/components/Modal.svelte';
 let loading=true,showAddModal=false,deviceLimit=1,allSites=[];
 onMount(async()=>{const [d,s]=await Promise.all([listDevices(),listSites()]);if(d.ok){devices.set(d.data.devices||[]);deviceLimit=d.data.limit||1}else notify(d.error||'Не удалось загрузить устройства','error');if(s.ok)allSites=s.data.sites||[];loading=false});
 $: onlineCount=$devices.filter(x=>x.status==='online').length;$: runningSites=allSites.filter(x=>x.site?.status==='running').length;$: offlineCount=$devices.length-onlineCount;
 function openDevice(device){goto('/devices/'+device.id)}
</script>
<svelte:head><title>Overview · Yevqo</title></svelte:head>
<div class="welcome-row"><div><div class="eyebrow"><span class="eyebrow-line"></span> WORKSPACE OVERVIEW</div><h1 class="page-title">Добро пожаловать, {$user?.username||'пользователь'}</h1><p class="page-desc">Ваша инфраструктура — под контролем. Всё важное в одном месте.</p></div><Button variant="primary" on:click={()=>showAddModal=true}>＋ Добавить устройство</Button></div>
{#if loading}<div class="empty">Загружаем инфраструктуру…</div>{:else}
<div class="overview-grid">
 <div class="hero-panel"><div class="hero-orb orb-one"></div><div class="hero-orb orb-two"></div><div class="hero-content"><span class="hero-kicker">CONTROL PLANE</span><h2>Ваша инфраструктура<br/>работает вместе.</h2><p>Управляйте устройствами, сайтами и базами данных из единой панели.</p><div class="hero-status"><i></i> Control plane активен <span>·</span> {$devices.length} устройств</div></div><div class="hero-graphic"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="core-mark">V</div><span class="node node-a">⌘</span><span class="node node-b">◈</span><span class="node node-c">▣</span></div></div>
 <div class="quick-panel"><div class="panel-topline"><span>QUICK ACCESS</span><span class="panel-dots">•••</span></div><a href="/databases" class="quick-link"><span class="quick-icon violet">◈</span><span><strong>Database servers</strong><small>Серверы и базы данных</small></span><b>↗</b></a><a href="/sites" class="quick-link"><span class="quick-icon cyan">◉</span><span><strong>Websites</strong><small>Размещённые приложения</small></span><b>↗</b></a><a href="/monitoring" class="quick-link"><span class="quick-icon green">⌁</span><span><strong>Monitoring</strong><small>Состояние инфраструктуры</small></span><b>↗</b></a><a href="/deployments" class="quick-link"><span class="quick-icon amber">⇧</span><span><strong>Deployments</strong><small>История и процессы запуска</small></span><b>↗</b></a></div>
</div>
<div class="metrics-grid">
 <div class="metric-card"><div class="metric-top"><span>Устройства</span><span class="metric-icon">▣</span></div><div class="metric-value">{$devices.length}<small> / {deviceLimit}</small></div><div class="metric-foot">Подключённые Android-хосты</div><div class="metric-track"><i style="width:{Math.min(100,deviceLimit?($devices.length/deviceLimit)*100:0)}%"></i></div></div>
 <div class="metric-card"><div class="metric-top"><span>Онлайн</span><span class="metric-icon green">●</span></div><div class="metric-value">{onlineCount}</div><div class="metric-foot"><span class="status-inline"></span>{offlineCount} офлайн</div></div>
 <div class="metric-card"><div class="metric-top"><span>Сайты</span><span class="metric-icon cyan">◉</span></div><div class="metric-value">{allSites.length}</div><div class="metric-foot">{runningSites} работают сейчас</div></div>
 <div class="metric-card"><div class="metric-top"><span>Базы данных</span><span class="metric-icon violet">◈</span></div><div class="metric-value">—</div><div class="metric-foot">Откройте Database servers</div></div>
</div>
<div class="section-header"><div><h2 class="section-title">Ваши устройства</h2><p class="section-subtitle">Подключённые хосты и их текущее состояние</p></div><a href="/devices" class="view-link">Все устройства <span>→</span></a></div>
{#if $devices.length===0}<div class="empty"><div class="empty-symbol">▣</div><h3>Пока нет подключённых устройств</h3><p class="empty-hint">Установите Yevqo Agent в Termux, чтобы добавить первый Android-хост.</p><div class="empty-action"><Button variant="primary" on:click={()=>showAddModal=true}>Подключить устройство</Button></div></div>
{:else}<div class="device-grid">{#each $devices as device (device.id)}<button class="device-card" on:click={()=>openDevice(device)}><div class="device-top"><span class="device-symbol">▣</span><StatusDot status={device.status}/></div><div class="device-title">{device.hostname||device.device_id?.slice(0,8)||'Android device'}</div><div class="device-id">{device.device_id?.slice(0,18)||'—'}</div><div class="device-divider"></div><div class="device-stats"><span>IP <b>{device.tailscale_ip||'—'}</b></span><span>Сайты <b>{device.site_count||0}</b></span></div></button>{/each}</div>{/if}
<div class="section-header"><div><h2 class="section-title">Последние сайты</h2><p class="section-subtitle">Приложения на подключённых устройствах</p></div><a href="/sites" class="view-link">Все сайты <span>→</span></a></div>
{#if allSites.length===0}<div class="empty compact-empty">Здесь появятся сайты, размещённые на ваших устройствах.</div>{:else}<div class="sites-table-wrap"><table class="sites-table"><thead><tr><th>САЙТ</th><th>УСТРОЙСТВО</th><th>RUNTIME</th><th>ПОРТ</th><th>СТАТУС</th></tr></thead><tbody>{#each allSites.slice(0,6) as item (item.device_id+'-'+item.site.site_id)}<tr on:click={()=>openDevice({id:item.device_id})}><td><strong>{item.site.site_id}</strong></td><td>{item.device_name||'Android host'}</td><td>{item.site.runtime}</td><td class="mono">:{item.site.port}</td><td><StatusDot status={item.site.status}/></td></tr>{/each}</tbody></table></div>{/if}
{/if}
<Modal open={showAddModal} title="Добавить устройство" onClose={()=>showAddModal=false}><p class="modal-text">Чтобы подключить новое устройство:</p><ol class="modal-steps"><li>Установите Termux на телефон.</li><li>Запустите <code>bash scripts/install-agent.sh</code>.</li><li>Введите URL сервера и код привязки.</li><li>Запустите <code>sv start veltrix-agent</code>.</li></ol><p class="modal-text">Код привязки: <code class="token">{$user?.referral_code||'—'}</code></p><svelte:fragment slot="footer"><Button on:click={()=>showAddModal=false}>Закрыть</Button></svelte:fragment></Modal>
